import { useCallback } from "react";
import type { GoogleFormConfig } from "./config";

type FormFields = Record<string, string>;

type UseGoogleFormSubmitParams = {
  form: GoogleFormConfig;
};

export const useGoogleFormSubmit = ({
  form,
}: UseGoogleFormSubmitParams) => {
  const submit = useCallback(
    async (fields: FormFields) => {
      const url =
        `https://docs.google.com/forms/d/e/${form.formId}/formResponse`;

      const body = new URLSearchParams();

      Object.entries(fields).forEach(([entryId, value]) => {
        body.append(entryId, value);
      });

      try {
        await fetch(url, {
          method: "POST",
          mode: "no-cors",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body,
        });

        return {
          success: true,
        };
      } catch (err) {
        return {
          success: false,
          error: err,
        };
      }
    },
    [form]
  );

  return {
    submit,
  };
};
