import { useSyncExternalStore } from "react";
import { createLiveStore } from "../../modules/shared/liveStore";
import { loadDocument } from "../../modules/supabase/documents";
import { usingSupabase } from "../../modules/supabase/enabled";
import { PATH } from "../../contracts/getApplications";
import { parseDocument } from "../../modules/gh-apply/applicationsStore";
import { activeApplication } from "../../modules/gh-apply/applicationRules";
import { applicationsApi } from "../../modules/gh-apply/applicationsApi";

type Active = ReturnType<typeof activeApplication> | null;
const store = createLiveStore<Active>(null, async () => {
  if (!usingSupabase()) {
    const result = await applicationsApi.load();
    return result.remote ? activeApplication(result.doc) ?? null : null;
  }
  const result = await loadDocument<unknown>(PATH);
  if (!result.ok) throw new Error(result.error.message);
  if (result.data === null) return null;
  const doc = parseDocument(result.data);
  if (!doc) throw new Error("Invalid application document");
  return activeApplication(doc) ?? null;
});

export function useActiveApplication() {
  return useSyncExternalStore(store.subscribe, store.getSnapshot, store.getServerSnapshot);
}
