// Styling for the application page shell.
//
// The form itself is rendered by the shared PPM GForm component and styled
// through template-1; everything here is the page around it — the banner, the
// two-column layout, the aside, and the success state.
//
// The banner follows the same reasoning as the final CTA: a flat wash over the
// whole photograph would make it pointless, so the scrim is weighted to the
// left where the type sits and thins out to the right, where the image is left
// to read as an image.

import brand from "../brand";

export type ApplicationTemplate = {
  css: string;
  rootClass: string;
};

const color = {
  /** Behind the banner photograph while it loads. */
  bannerBase: brand.colors.primary,
  /**
   * Left-weighted so the headline sits on near-solid charcoal while the right
   * of the frame stays close to the original exposure.
   */
  bannerScrim:
    "linear-gradient(to right, rgba(31,35,40,.93) 0%, rgba(31,35,40,.82) 28%, rgba(31,35,40,.60) 52%, rgba(31,35,40,.34) 76%, rgba(31,35,40,.22) 100%)",
  /** A little extra weight top and bottom, tying the banner to the header. */
  bannerScrimEdge:
    "linear-gradient(to bottom, rgba(31,35,40,.42) 0%, rgba(31,35,40,0) 26%, rgba(31,35,40,0) 68%, rgba(31,35,40,.38) 100%)",

  background: brand.colors.background,

  rule: brand.colors.accent,
  eyebrow: brand.colors.accent,
  title: brand.colors.onPrimary,
  lede: "rgba(255, 255, 255, 0.80)",

  crumbLink: "rgba(255, 255, 255, 0.66)",
  crumbLinkHover: brand.colors.accent,
  crumbCurrent: "rgba(255, 255, 255, 0.92)",
  crumbSeparator: brand.colors.accent,

  formBorder: brand.colors.border,
  formShadow: "0 1px 3px rgba(31, 35, 40, .04)",
  legend: brand.colors.primary,
  legendRule: brand.colors.accent,
  note: brand.colors.textMuted,

  asideBackground: brand.colors.backgroundAlt,
  asideTitle: brand.colors.primary,
  asideText: brand.colors.textMuted,
  asideIcon: brand.colors.accent,
  asideDivider: brand.colors.border,

  successBackground: brand.colors.backgroundAlt,
  successIcon: brand.colors.accent,
  successTitle: brand.colors.primary,
  successText: brand.colors.textMuted,

  focus: brand.colors.accent,
};

const layout = {
  maxWidth: 1280,
  bannerHeight: 440,
  bannerHeightTablet: 380,
  bannerHeightMobile: 320,
  bannerContentMaxWidth: 660,
  /** Very slow drift, the same restraint as the CTA. */
  bannerZoomTo: 1.05,
  ruleWidth: 44,
  formColumn: "62fr",
  asideColumn: "38fr",
  radius: 2,
  stackBelow: 940,
};

const spacing = {
  gutter: 40,
  gutterCompact: 20,
  sectionTop: 84,
  sectionBottom: 104,
  sectionTopCompact: 56,
  sectionBottomCompact: 72,
  columnGap: 56,
  columnGapCompact: 40,
  ruleGap: 18,
  eyebrowGap: 18,
  titleGap: 18,
  ledeGap: 26,
  formPadding: 36,
  formPaddingCompact: 24,
  legendGap: 26,
  groupGap: 40,
  asidePadding: 30,
};

const typography = {
  eyebrowFamily: brand.typography.body,
  eyebrowSize: 11,
  eyebrowWeight: brand.typography.weight.semibold,
  eyebrowTracking: "0.22em",

  titleFamily: brand.typography.heading,
  titleSize: "clamp(32px, 4vw, 56px)",
  titleWeight: brand.typography.weight.heading,
  titleTracking: brand.typography.tracking.tight,

  ledeFamily: brand.typography.body,
  ledeSize: "clamp(15px, 1.2vw, 17px)",
  ledeLeading: 1.7,

  crumbFamily: brand.typography.body,
  crumbSize: 12.5,

  legendFamily: brand.typography.heading,
  legendSize: 18,
  legendWeight: brand.typography.weight.heading,

  asideTitleFamily: brand.typography.heading,
  asideTitleSize: 16,
  asideTitleWeight: brand.typography.weight.heading,
  asideTextFamily: brand.typography.body,
  asideTextSize: 14,
  asideTextLeading: 1.7,

  noteFamily: brand.typography.body,
  noteSize: 12.5,
  noteLeading: 1.65,
};

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
/* ── banner ───────────────────────────────────────────── */
.kr-apply-head {
  position: relative;
  display: flex;
  align-items: center;
  min-height: ${layout.bannerHeight}px;
  background: ${color.bannerBase};
  overflow: hidden;
  isolation: isolate;
}

.kr-apply-head__media { position: absolute; inset: 0; z-index: 0; }
.kr-apply-head__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  /* The source is already cropped to keep every head; anchoring to the top
     means any further crop the viewport forces also comes off the bottom. */
  object-position: center top;
  display: block;
  /* Runs once on arrival rather than on scroll: the banner is already on
     screen when the page loads, so there is nothing to wait for. */
  animation: kr-apply-drift 16s linear both;
}
.kr-apply-head__scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: ${color.bannerScrim}, ${color.bannerScrimEdge};
  pointer-events: none;
}

.kr-apply-head__inner {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-apply-head__content { max-width: ${layout.bannerContentMaxWidth}px; }

/* Gold rule leading the eyebrow — the recurring accent across the site. */
.kr-apply-head__rule {
  display: block;
  width: ${layout.ruleWidth}px;
  height: 2px;
  margin: 0 0 ${spacing.ruleGap}px;
  background: ${color.rule};
  transform-origin: left center;
  animation: kr-apply-rule 620ms ${ease} both;
}
.kr-apply-head__eyebrow {
  margin: 0 0 ${spacing.eyebrowGap}px;
  color: ${color.eyebrow};
  font-family: ${typography.eyebrowFamily};
  font-size: ${typography.eyebrowSize}px;
  font-weight: ${typography.eyebrowWeight};
  letter-spacing: ${typography.eyebrowTracking};
  text-transform: uppercase;
  animation: kr-apply-rise 700ms ${ease} 100ms both;
}
.kr-apply-head__title {
  margin: 0 0 ${spacing.titleGap}px;
  max-width: 16ch;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: 1.08;
  animation: kr-apply-rise 700ms ${ease} 180ms both;
}
.kr-apply-head__lede {
  margin: 0 0 ${spacing.ledeGap}px;
  max-width: 54ch;
  color: ${color.lede};
  font-family: ${typography.ledeFamily};
  font-size: ${typography.ledeSize};
  line-height: ${typography.ledeLeading};
  animation: kr-apply-rise 700ms ${ease} 260ms both;
}
.kr-apply-head__crumbs { animation: kr-apply-rise 700ms ${ease} 340ms both; }
.kr-apply-head__crumbs ol {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-apply-head__crumbs li {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: ${typography.crumbFamily};
  font-size: ${typography.crumbSize}px;
}
.kr-apply-head__crumbs li + li::before { content: "/"; color: ${color.crumbSeparator}; }
.kr-apply-head__crumbs a {
  color: ${color.crumbLink};
  text-decoration: none;
  transition: color .24s ${ease};
}
.kr-apply-head__crumbs a:hover { color: ${color.crumbLinkHover}; }
.kr-apply-head__crumbs a:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }
.kr-apply-head__crumbs [aria-current="page"] { color: ${color.crumbCurrent}; }

@keyframes kr-apply-rise {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: none; }
}
@keyframes kr-apply-rule {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}
@keyframes kr-apply-drift {
  from { transform: scale(1); }
  to { transform: scale(${layout.bannerZoomTo}); }
}

/* ── body ─────────────────────────────────────────────── */
.kr-apply {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
}
.kr-apply__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  display: grid;
  grid-template-columns: ${layout.formColumn} ${layout.asideColumn};
  align-items: start;
  gap: ${spacing.columnGap}px;
}

.kr-apply__form {
  padding: ${spacing.formPadding}px;
  border: 1px solid ${color.formBorder};
  border-radius: ${layout.radius}px;
  box-shadow: ${color.formShadow};
}

/* Field groups: the JSON declares which group each field belongs to, and the
   page renders one form section per group. */
.kr-apply__group + .kr-apply__group { margin-top: ${spacing.groupGap}px; }
.kr-apply__legend {
  margin: 0 0 ${spacing.legendGap}px;
  color: ${color.legend};
  font-family: ${typography.legendFamily};
  font-size: ${typography.legendSize}px;
  font-weight: ${typography.legendWeight};
  letter-spacing: -0.02em;
}
.kr-apply__legend-rule {
  display: block;
  width: 34px;
  height: 2px;
  margin-top: 10px;
  background: ${color.legendRule};
}

.kr-apply__note {
  margin: 24px 0 0;
  color: ${color.note};
  font-family: ${typography.noteFamily};
  font-size: ${typography.noteSize}px;
  line-height: ${typography.noteLeading};
}

/* ── aside ────────────────────────────────────────────── */
.kr-apply__aside {
  padding: ${spacing.asidePadding}px;
  background: ${color.asideBackground};
  border-radius: ${layout.radius}px;
  position: sticky;
  top: 110px;
}
.kr-apply__aside-title {
  margin: 0 0 16px;
  color: ${color.asideTitle};
  font-family: ${typography.asideTitleFamily};
  font-size: ${typography.asideTitleSize}px;
  font-weight: ${typography.asideTitleWeight};
  letter-spacing: -0.02em;
}
.kr-apply__aside-list { margin: 0; padding: 0; list-style: none; }
.kr-apply__aside-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  color: ${color.asideText};
  font-family: ${typography.asideTextFamily};
  font-size: ${typography.asideTextSize}px;
  line-height: ${typography.asideTextLeading};
}
.kr-apply__aside-icon { color: ${color.asideIcon}; display: inline-flex; margin-top: 3px; flex-shrink: 0; }
.kr-apply__aside-divider {
  height: 1px;
  margin: ${spacing.asidePadding}px 0;
  background: ${color.asideDivider};
}
.kr-apply__aside-text {
  margin: 0 0 14px;
  color: ${color.asideText};
  font-family: ${typography.asideTextFamily};
  font-size: ${typography.asideTextSize}px;
  line-height: ${typography.asideTextLeading};
}

/* ── success ──────────────────────────────────────────── */
.kr-apply__success {
  padding: 48px 40px;
  background: ${color.successBackground};
  border-radius: ${layout.radius}px;
  text-align: center;
}
.kr-apply__success-icon { color: ${color.successIcon}; display: inline-flex; margin-bottom: 18px; }
.kr-apply__success-title {
  margin: 0 0 12px;
  color: ${color.successTitle};
  font-family: ${typography.asideTitleFamily};
  font-size: 24px;
  font-weight: ${typography.asideTitleWeight};
  letter-spacing: -0.02em;
}
.kr-apply__success-text {
  margin: 0 auto;
  max-width: 46ch;
  color: ${color.successText};
  font-family: ${typography.asideTextFamily};
  font-size: 15px;
  line-height: 1.7;
}

/* ── responsive ───────────────────────────────────────── */
@media (max-width: 1080px) {
  .kr-apply-head { min-height: ${layout.bannerHeightTablet}px; }
}

@media (max-width: ${layout.stackBelow}px) {
  .kr-apply-head { min-height: ${layout.bannerHeightMobile}px; }
  /* Narrow frames leave no clear right-hand side, so the scrim becomes an
     even wash — otherwise the type sits on whatever the crop happens to show. */
  .kr-apply-head__scrim {
    background-image:
      linear-gradient(to right, rgba(31,35,40,.90) 0%, rgba(31,35,40,.74) 100%),
      ${color.bannerScrimEdge};
  }
  .kr-apply-head__inner,
  .kr-apply__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-apply {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-apply__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
  }
  /* Requirements belong above the form on a phone, where they are read first. */
  .kr-apply__aside { position: static; order: -1; }
  .kr-apply__form { padding: ${spacing.formPaddingCompact}px; }
}

@media (prefers-reduced-motion: reduce) {
  /* Every element is already in its final state without the animation, so
     switching them off shows the finished banner rather than nothing. */
  .kr-apply-head__image,
  .kr-apply-head__rule,
  .kr-apply-head__eyebrow,
  .kr-apply-head__title,
  .kr-apply-head__lede,
  .kr-apply-head__crumbs { animation: none; }
  .kr-apply-head__crumbs a { transition: none; }
}
`;

const template: ApplicationTemplate = {
  css,
  rootClass: "kr-apply",
};

export default template;
